//! The constitutive laws of VISION.md §4, as data.
//!
//! This table is the **single source of truth** for both the human-readable contract
//! (`docs/GATES.md`, generated by `xtask gates`) and the future enforcement code that will
//! flip each [`LawStatus::Spec`] to [`LawStatus::Gated`] as its block lands. A law that is
//! not in this table does not exist, and a gate that enforces something absent from this
//! table measures shadow, not law — the code and the contract must name the same list.
//!
//! Bounds are written precisely enough to be measured; where the exact number requires
//! reference-hardware calibration (a Block 1 open item in `AUDIT.md`), the bound says so.

/// Whether a bound is specified (the target we build to) or gated (measured in CI on every
/// commit with the harness named by the law).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LawStatus {
    /// Specified target; enforcement code arrives with its block.
    Spec,
    /// Measured in CI; a regression fails the build.
    Gated,
}

impl LawStatus {
    /// The printable token used in the generated contract.
    pub const fn token(self) -> &'static str {
        match self {
            Self::Spec => "spec",
            Self::Gated => "gated",
        }
    }
}

/// One constitutive budget of VISION.md §4.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Law {
    /// Stable identifier (`L-1` …). Referenced from code, docs, and audits; never reused.
    pub id: &'static str,
    /// Short title.
    pub name: &'static str,
    /// The bound, written so it can be measured.
    pub bound: &'static str,
    /// The roadmap block whose gate enforces it.
    pub block: &'static str,
    /// Specification status.
    pub status: LawStatus,
}

